                {"text": "Massage Therapy", "selected_icon": {"value": "fas fa-chevron-right", "library": "fa-solid"}, "link": {"url": "/services/massage-therapy"}},
                {"text": "Sports Rehabilitation", "selected_icon": {"value": "fas fa-chevron-right", "library": "fa-solid"}, "link": {"url": "/services/sports-rehabilitation"}},
                {"text": "Posture Correction", "selected_icon": {"value": "fas fa-chevron-right", "library": "fa-solid"}, "link": {"url": "/services/posture-correction"}},
